// ============================================================
// NORMALIZE: flatten every source into a standard job object
// ============================================================
const result = [];

for (const item of $input.all()) {
  const raw = item.json;

  let job = {
    job_title: '',
    company: '',
    job_url: '',
    source: item.json._source || '',
    location_text: '',
    salary: '',
    description: '',
    posted_date: '',
    tags: '',
    job_id: ''
  };

  // ---- RemoteOK (array response: skip index 0 which is legal notice) ----
  if (raw && raw[0] && raw[0].legal) {
    const jobs = Array.isArray(raw) ? raw.slice(1) : [];
    for (const j of jobs) {
      if (!j || !j.position) continue;
      result.push({ json: {
        job_title: j.position || '',
        company: j.company || '',
        job_url: j.url || `https://remoteok.com/remote-jobs/${j.slug}`,
        source: 'RemoteOK',
        location_text: j.location || 'Worldwide',
        salary: j.salary_min ? `$${j.salary_min}–$${j.salary_max}/yr` : (j.salary || ''),
        description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: j.date || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
        job_id: `remoteok_${j.id || j.slug || Math.random().toString(36).substr(2,8)}`
      }});
    }
    continue;
  }

  // ---- Remotive (response has { jobs: [...] }) ----
  if (raw && Array.isArray(raw.jobs)) {
    for (const j of raw.jobs) {
      if (!j || !j.title) continue;
      result.push({ json: {
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        source: 'Remotive',
        location_text: j.candidate_required_location || 'Worldwide',
        salary: j.salary || '',
        description: (j.description || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: j.publication_date || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
        job_id: `remotive_${j.id}`
      }});
    }
    continue;
  }

  // ---- Himalayas API ({ jobs: [...] } or { data: [...] }) ----
  const himJobs = raw.jobs || raw.data || null;
  if (Array.isArray(himJobs) && himJobs.length > 0 && (himJobs[0].title || himJobs[0].job_title)) {
    for (const j of himJobs) {
      if (!j || !(j.title || j.job_title)) continue;
      result.push({ json: {
        job_title: j.title || j.job_title || '',
        company: j.company?.name || j.company_name || j.company || '',
        job_url: j.url || j.job_url || '',
        source: 'Himalayas',
        location_text: j.location || j.locationRestrictions?.join(', ') || 'Worldwide',
        salary: j.salary || j.compensation || '',
        description: (j.description || j.content || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
        posted_date: j.publishedAt || j.createdAt || j.posted_date || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.skills || ''),
        job_id: `himalayas_${j.id || j.slug || Math.random().toString(36).substr(2,8)}`
      }});
    }
    continue;
  }

  // ---- RSS items (WWR, Dynamite Jobs) ----
  if (raw.link || raw.guid || raw.pubDate) {
    let srcName = 'RSS';
    const urlStr = raw.link || raw.guid || '';
    if (urlStr.includes('weworkremotely')) srcName = 'WeWorkRemotely';
    else if (urlStr.includes('dynamitejobs')) srcName = 'DynamiteJobs';

    // Extract company from title "Job Title at Company" pattern
    const titleStr = raw.title || '';
    const atIdx = titleStr.lastIndexOf(' at ');
    const jobTitle = atIdx > 0 ? titleStr.substring(0, atIdx).trim() : titleStr;
    const company = atIdx > 0 ? titleStr.substring(atIdx + 4).trim() : (raw['dc:creator'] || raw.author || '');

    const url = raw.link || raw.guid || '';
    if (!url) continue;

    result.push({ json: {
      job_title: jobTitle,
      company,
      job_url: url,
      source: srcName,
      location_text: (raw.categories || []).join(', ') || 'Remote',
      salary: '',
      description: (raw.contentSnippet || raw.content || raw.summary || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
      posted_date: raw.pubDate || raw.isoDate || '',
      tags: Array.isArray(raw.categories) ? raw.categories.join(', ') : '',
      job_id: `rss_${Buffer.from(url).toString('base64').substring(0, 24)}`
    }});
    continue;
  }

  // ---- Generic fallback (Wellfound, YC, Otta scraped HTML/JSON) ----
  const url = raw.url || raw.job_url || raw.link || raw.applyUrl || '';
  const title = raw.title || raw.job_title || raw.position || raw.name || '';
  if (!url || !title) continue;

  let srcName = 'Unknown';
  if (url.includes('wellfound') || url.includes('angel.co')) srcName = 'Wellfound';
  else if (url.includes('workatastartup') || url.includes('ycombinator')) srcName = 'YCombinator';
  else if (url.includes('otta')) srcName = 'Otta';

  result.push({ json: {
    job_title: title,
    company: raw.company || raw.company_name || raw.startup_name || '',
    job_url: url,
    source: srcName,
    location_text: raw.location || raw.location_text || raw.remote_policy || '',
    salary: raw.salary || raw.compensation || raw.salary_range || '',
    description: (raw.description || raw.body || raw.content || '').replace(/<[^>]*>/g, ' ').substring(0, 3000),
    posted_date: raw.posted_date || raw.created_at || raw.publishedAt || '',
    tags: Array.isArray(raw.tags) ? raw.tags.join(', ') : (raw.tags || ''),
    job_id: `${srcName.toLowerCase()}_${Buffer.from(url).toString('base64').substring(0, 20)}`
  }});
}

return result;

// ============================================================
// DEDUPLICATE: skip jobs already in Google Sheets
// ============================================================
const existing = $('Read Existing URLs').all();
const seenUrls = new Set(existing.map(i => (i.json.job_url || '').trim()).filter(Boolean));
const seenKeys = new Set(existing.map(i => `${(i.json.company||'').toLowerCase().trim()}__${(i.json.job_title||'').toLowerCase().trim()}`).filter(k => k !== '__'));

const batchSeen = new Set();
const result = [];

for (const item of $input.all()) {
  const url = (item.json.job_url || '').trim();
  const key = `${(item.json.company||'').toLowerCase().trim()}__${(item.json.job_title||'').toLowerCase().trim()}`;

  if (!url) continue;
  if (seenUrls.has(url)) continue;
  if (key !== '__' && seenKeys.has(key)) continue;
  if (batchSeen.has(url)) continue;

  batchSeen.add(url);
  result.push(item);
}

return result;

// ============================================================
// TAIWAN HARD FILTER: keyword-based pre-screen before AI
// ============================================================
const REJECT = [
  /\bus[- ]?only\b/i, /\busa[- ]?only\b/i, /\bunited states only\b/i,
  /\bcanada[- ]?only\b/i, /\buk[- ]?only\b/i, /\bunited kingdom only\b/i,
  /\beu[- ]?only\b/i, /\beurope[- ]?only\b/i, /\baustralia[- ]?only\b/i,
  /\bnorth america only\b/i,
  /\bmust be based in (the )?(us|usa|uk|eu|europe|canada|australia)\b/i,
  /\bmust live in (the )?(us|usa|uk|eu|europe|canada|australia)\b/i,
  /\bmust be authorized to work in\b/i,
  /\bwork authorization required\b/i,
  /\blocal work permit required\b/i,
  /\bsecurity clearance required\b/i,
  /\b(greencard|green card) required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i,
  /\boffice required\b/i, /\bin-office\b/i,
  /\bremote within (the )?(us|usa|uk|eu|europe|canada|australia)\b/i,
  /\blocal candidates only\b/i,
  /\bcitizens? or (permanent )?residents? only\b/i,
  /\bno international\b/i
];

const KEEP = [
  /\bworldwide remote\b/i, /\bglobal remote\b/i,
  /\bwork from anywhere\b/i, /\bwfa\b/i,
  /\banywhere in the world\b/i, /\bopen to all locations\b/i,
  /\bno location restriction\b/i, /\bopen to international\b/i,
  /\bapac\b/i, /\basia.?pacific\b/i, /\btaiwan\b/i,
  /\binternational contractor/i, /\bb2b contractor\b/i,
  /\bcontractor role\b/i, /\bcontract position\b/i,
  /\bdeel\b/i, /\bremote\.com\b/i, /\boyster\b/i,
  /\beor supported\b/i, /\bemployer of record\b/i,
  /\bhire.? globally\b/i, /\bglobally distributed\b/i,
  /\bdistributed team\b/i, /\bremote.?first\b/i,
  /\baccepting (applications|candidates) (from )?(anywhere|worldwide|globally)\b/i
];

const result = [];

for (const item of $input.all()) {
  const text = `${item.json.location_text || ''} ${item.json.description || ''} ${item.json.job_title || ''}`.toLowerCase();

  const keepHits = KEEP.filter(p => p.test(text)).map(p => p.source);
  const rejectHits = REJECT.filter(p => p.test(text)).map(p => p.source);

  const hasKeep = keepHits.length > 0;
  const hasReject = rejectHits.length > 0;

  // Hard reject only when reject signals with no overriding keep signals
  if (hasReject && !hasKeep) {
    item.json._hard_filter = 'rejected';
    item.json._reject_reason = rejectHits.join(' | ');
    // We still emit for tracking in the score node
  } else {
    item.json._hard_filter = hasKeep ? 'keep' : 'neutral';
    item.json._keep_signals = keepHits.join(', ');
    result.push(item);
  }
}

return result;

// ============================================================
// SCORE + FILTER: combine AI response with scoring logic
// ============================================================
const ASYNC_KEEP = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote.?first', 'low meeting',
  'work across time zones', 'no meeting', 'flexible working'
];
const ASYNC_REJECT = [
  'strict 9 to 5', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required',
  'must overlap full business day', '9-5 est', '9-5 pst', '9-5 cet',
  'must be available during.*business hours',
  'core hours.*est', 'core hours.*pst'
];

const ROLE_HIGH = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing', 'growth analyst', 'ai marketing',
  'ai automation', 'ai workflow', 'creative strategist',
  'martech', 'machine learning', 'ml engineer', 'analytics engineer'
];
const ROLE_MED = [
  'analyst', 'marketing', 'growth', 'automation', 'insights',
  'reporting', 'analytics', 'seo', 'ppc', 'sem', 'digital marketing',
  'product analyst', 'operations analyst', 'revenue analyst'
];

const result = [];

for (const item of $input.all()) {
  const data = { ...item.json };

  // Parse OpenAI response
  let ai = {};
  try {
    const raw = data.choices?.[0]?.message?.content || '{}';
    ai = JSON.parse(raw.replace(/```json\n?|\n?```/g, '').trim());
  } catch (e) {
    ai = {
      taiwan_eligible: 'unclear', decision: 'manual_check',
      location_risk: 'medium', timezone_risk: 'medium',
      contractor_possible: 'unclear', reason: 'AI parse error'
    };
  }

  // Restore original job fields (OpenAI response replaces item.json)
  // The batch input was passed in the request body — get original from context
  // Note: SplitInBatches passes through items; AI response is new item.json
  // We need to join. The approach: store original in _job field before AI call,
  // then restore here. (See note below about pairedItem)
  // For this workflow, we use the trick of reading from $('Taiwan Hard Filter').item
  // via paired items. Simplified: assume data has _job_title etc. from before.
  // If not present, we rely on the AI response body being appended to original.
  // Best practice: before AI call, merge fields. Done via Set node ideally.
  // Fallback: reconstruct from AI prompt echo if available.

  const text = `${data._orig_desc || data.description || ''} ${data._orig_location || data.location_text || ''}`.toLowerCase();
  const titleText = (data._orig_title || data.job_title || '').toLowerCase();

  // ---- ASYNC LEVEL ----
  const hasAsyncKeep = ASYNC_KEEP.some(k => new RegExp(k, 'i').test(text));
  const hasAsyncReject = ASYNC_REJECT.some(k => new RegExp(k, 'i').test(text));
  let asyncLevel;
  if (/\b(async|asynchronous)\b/i.test(text)) asyncLevel = 'high';
  else if (/flexible hours|flexible schedule/i.test(text)) asyncLevel = 'high';
  else if (/distributed team/i.test(text)) asyncLevel = 'medium';
  else if (/remote.?first/i.test(text)) asyncLevel = 'medium';
  else asyncLevel = 'unknown';

  if (hasAsyncReject && !hasAsyncKeep) {
    asyncLevel = 'sync';
    ai.timezone_risk = 'high';
  }

  // ---- SCORING ----
  let score = 0;

  // Taiwan eligibility (40 pts)
  const eligible = ai.taiwan_eligible || 'unclear';
  const locRisk = ai.location_risk || 'medium';
  if (eligible === 'yes' && locRisk === 'low') score += 40;
  else if (eligible === 'yes') score += 35;
  else if ((data._keep_signals || '').toLowerCase().includes('apac')) score += 30;
  else if (eligible === 'unclear' && locRisk !== 'high') score += 20;
  else score += 0;

  // Async fit (25 pts)
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 18;
  else if (asyncLevel === 'unknown') score += 10;
  else score += 0; // sync = 0

  // Role fit (25 pts)
  let roleCategory = 'other';
  let roleScore = 0;
  const combined = `${titleText} ${text}`;
  if (ROLE_HIGH.some(r => new RegExp(r, 'i').test(combined))) {
    roleScore = 25; roleCategory = 'target';
  } else if (ROLE_MED.some(r => new RegExp(r, 'i').test(combined))) {
    roleScore = 15; roleCategory = 'adjacent';
  }
  score += roleScore;

  // Salary fit (up to 25 pts)
  const salaryStr = (data._orig_salary || data.salary || '').replace(/,/g, '');
  const salNums = (salaryStr.match(/\d{3,}/g) || []).map(Number);
  const maxSal = salNums.length ? Math.max(...salNums) : 0;
  let salScore = 0;
  if (maxSal > 0) {
    // Detect if annual (>20000) vs monthly
    const monthly = maxSal > 20000 ? maxSal / 12 : maxSal;
    if (monthly >= 5000) salScore = 25;
    else if (monthly >= 3000) salScore = 15;
    else salScore = 10;
  }
  score += salScore;

  // ---- DECISION ----
  let decision;
  if (eligible === 'no' || locRisk === 'high' || asyncLevel === 'sync' || score < 70) {
    decision = 'reject';
  } else if (eligible === 'unclear' && score >= 85 && locRisk === 'medium') {
    decision = 'manual_check';
  } else if (eligible === 'yes' && score >= 85 && asyncLevel !== 'sync') {
    decision = 'apply';
  } else if (score >= 70) {
    decision = 'review';
  } else {
    decision = 'reject';
  }

  // ---- WHY GOOD FIT ----
  const why = [];
  if (eligible === 'yes') why.push('Taiwan eligible');
  if (asyncLevel === 'high') why.push('Fully async');
  else if (asyncLevel === 'medium') why.push('Flexible hours');
  if (roleCategory === 'target') why.push('Target role match');
  if (salScore >= 15) why.push('Competitive salary');
  if (ai.contractor_possible === 'yes') why.push('Contractor-friendly');
  if ((data._keep_signals || '').includes('deel') || (data._keep_signals || '').includes('remote.com')) {
    why.push('EOR supported');
  }

  // ---- OUTPUT ----
  data.taiwan_eligible = eligible;
  data.taiwan_reason = ai.reason || '';
  data.location_risk = locRisk;
  data.timezone_risk = ai.timezone_risk || 'medium';
  data.contractor_possible = ai.contractor_possible || 'unclear';
  data.async_level = asyncLevel;
  data.role_category = roleCategory;
  data.score = score;
  data.why_good_fit = why.join(', ');
  data.decision = decision;
  data.date_found = new Date().toISOString().split('T')[0];
  data.application_status = 'new';
  data.notes = '';

  // Clean up internal fields
  delete data.choices;
  delete data._orig_desc;
  delete data._orig_title;
  delete data._orig_location;
  delete data._orig_salary;

  result.push({ json: data });
}

return result;

// ============================================================
// BUILD DAILY DIGEST: format email from all scored jobs
// ============================================================
const allJobs = $input.first().json.data || [];

allJobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const topJobs = allJobs.filter(j => j.decision !== 'reject' && (j.score || 0) >= 70);
const manualCheck = allJobs.filter(j => j.decision === 'manual_check');
const applyNow = allJobs.filter(j => j.decision === 'apply' && (j.score || 0) >= 85);
const rejected = allJobs.filter(j => j.decision === 'reject');

const rejStats = {
  us: rejected.filter(j => /(us only|usa only|north america only)/i.test(j._reject_reason || j.taiwan_reason || '')).length,
  eu: rejected.filter(j => /(eu only|europe only|uk only)/i.test(j._reject_reason || j.taiwan_reason || '')).length,
  hybrid: rejected.filter(j => /(hybrid|onsite|on-site)/i.test(j._reject_reason || j.taiwan_reason || '')).length,
  timezone: rejected.filter(j => j.timezone_risk === 'high').length,
  total: rejected.length
};

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Taipei'
});

let html = `<html><body style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; color: #222;">`;
html += `<h2 style="color: #1a56db;">🇹🇼 Daily Taiwan Eligible Async Remote Jobs</h2>`;
html += `<p style="color: #666;">📅 ${today}</p>`;
html += `<table style="width:100%; background:#f0f4ff; border-radius:8px; padding:12px; margin-bottom:16px;"><tr>`;
html += `<td style="text-align:center;"><strong>${topJobs.length}</strong><br><small>Top Jobs</small></td>`;
html += `<td style="text-align:center;"><strong>${applyNow.length}</strong><br><small>Apply Now</small></td>`;
html += `<td style="text-align:center;"><strong>${manualCheck.length}</strong><br><small>Manual Review</small></td>`;
html += `<td style="text-align:center;"><strong>${rejected.length}</strong><br><small>Rejected</small></td>`;
html += `</tr></table>`;

if (applyNow.length > 0) {
  html += `<h3 style="color:#15803d;">⭐ APPLY NOW (Score 85+)</h3>`;
  applyNow.forEach((job, i) => {
    html += `<div style="border:2px solid #15803d; border-radius:8px; padding:16px; margin-bottom:12px;">`;
    html += `<h4 style="margin:0 0 4px;">${i+1}. ${job.job_title}</h4>`;
    html += `<table style="width:100%; font-size:14px;"><tr><td><strong>Company:</strong> ${job.company}</td><td><strong>Score:</strong> ${job.score}/100</td></tr>`;
    html += `<tr><td><strong>Taiwan Eligible:</strong> ${(job.taiwan_eligible||'').toUpperCase()}</td><td><strong>Async Level:</strong> ${job.async_level||'unknown'}</td></tr>`;
    html += `<tr><td><strong>Timezone Risk:</strong> ${job.timezone_risk||'unknown'}</td><td><strong>Salary:</strong> ${job.salary||'Not listed'}</td></tr>`;
    html += `<tr><td colspan="2"><strong>Reason:</strong> ${job.taiwan_reason||'N/A'}</td></tr>`;
    html += `<tr><td colspan="2"><strong>Why Jerry fits:</strong> ${job.why_good_fit||'N/A'}</td></tr>`;
    html += `</table>`;
    html += `<a href="${job.job_url}" style="display:inline-block; margin-top:8px; padding:8px 16px; background:#1a56db; color:white; border-radius:4px; text-decoration:none;">Apply →</a>`;
    html += `</div>`;
  });
}

if (topJobs.filter(j => j.decision !== 'apply' || j.score < 85).length > 0) {
  const reviewJobs = topJobs.filter(j => !(j.decision === 'apply' && j.score >= 85));
  html += `<h3 style="color:#1a56db;">🏆 TOP JOBS (Score 70+)</h3>`;
  reviewJobs.slice(0, 8).forEach((job, i) => {
    html += `<div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">`;
    html += `<h4 style="margin:0 0 4px;">${i+1}. ${job.job_title}</h4>`;
    html += `<table style="width:100%; font-size:13px;"><tr>`;
    html += `<td><strong>Company:</strong> ${job.company}</td><td><strong>Score:</strong> ${job.score}/100</td></tr>`;
    html += `<tr><td><strong>Taiwan:</strong> ${(job.taiwan_eligible||'').toUpperCase()}</td><td><strong>Async:</strong> ${job.async_level||'?'}</td></tr>`;
    html += `<tr><td><strong>Timezone Risk:</strong> ${job.timezone_risk||'?'}</td><td><strong>Salary:</strong> ${job.salary||'?'}</td></tr>`;
    html += `<tr><td colspan="2"><strong>Why fits:</strong> ${job.why_good_fit||'N/A'}</td></tr>`;
    html += `</table>`;
    html += `<a href="${job.job_url}" style="font-size:13px;">View Job →</a>`;
    html += `</div>`;
  });
}

if (manualCheck.length > 0) {
  html += `<h3 style="color:#d97706;">🔍 MANUAL REVIEW NEEDED</h3>`;
  html += `<p style="font-size:13px; color:#666;">Taiwan eligibility unclear but score is high — check these yourself:</p>`;
  manualCheck.slice(0, 5).forEach((job, i) => {
    html += `<div style="border:1px solid #fbbf24; border-radius:6px; padding:10px; margin-bottom:8px; font-size:13px;">`;
    html += `<strong>${i+1}. ${job.job_title}</strong> @ ${job.company} — Score: ${job.score}<br>`;
    html += `Reason: ${job.taiwan_reason||'Unclear'}<br>`;
    html += `<a href="${job.job_url}">View →</a>`;
    html += `</div>`;
  });
}

html += `<div style="background:#fef2f2; border-radius:8px; padding:12px; margin-top:16px;">`;
html += `<h3 style="margin:0 0 8px; color:#dc2626;">❌ Rejected Summary</h3>`;
html += `<ul style="margin:0; font-size:13px;">`;
html += `<li>US/North America only: <strong>${rejStats.us}</strong></li>`;
html += `<li>EU/Europe/UK only: <strong>${rejStats.eu}</strong></li>`;
html += `<li>Hybrid/Onsite: <strong>${rejStats.hybrid}</strong></li>`;
html += `<li>Timezone risk: <strong>${rejStats.timezone}</strong></li>`;
html += `<li>Total rejected: <strong>${rejStats.total}</strong></li>`;
html += `</ul></div>`;

html += `<p style="font-size:11px; color:#999; margin-top:20px; text-align:center;">Taiwan Job Hunter — built for async global work 🤖</p>`;
html += `</body></html>`;

// Also build plain text fallback
let text = `Taiwan Eligible Async Remote Jobs — ${today}\n`;
text += `${'='.repeat(50)}\n\n`;
text += `Summary: ${topJobs.length} top jobs | ${applyNow.length} apply now | ${manualCheck.length} manual check | ${rejected.length} rejected\n\n`;

topJobs.slice(0, 10).forEach((job, i) => {
  text += `${i+1}. ${job.job_title}\n`;
  text += `   Company: ${job.company}\n`;
  text += `   Score: ${job.score}/100 | Taiwan: ${job.taiwan_eligible} | Async: ${job.async_level}\n`;
  text += `   Salary: ${job.salary || 'Not listed'}\n`;
  text += `   Why fits: ${job.why_good_fit || 'N/A'}\n`;
  text += `   Apply: ${job.job_url}\n\n`;
});

text += `Rejected: US=${rejStats.us} | EU=${rejStats.eu} | Hybrid=${rejStats.hybrid} | Timezone=${rejStats.timezone}\n`;

return [{ json: {
  html_body: html,
  text_body: text,
  subject: `🇹🇼 [${today.split(',')[0]}] Taiwan Jobs: ${applyNow.length} to apply, ${topJobs.length} top picks`,
  top_jobs_count: topJobs.length,
  apply_now_count: applyNow.length,
  manual_check_count: manualCheck.length,
  rejected_count: rejected.length,
  all_jobs: allJobs
}}];

// Extract cover letter and store it with the job
const coverText = $json.choices?.[0]?.message?.content || 'Cover letter generation failed';

return [{ json: {
  ...$input.first().json,
  cover_letter: coverText,
  cover_letter_generated: new Date().toISOString().split('T')[0]
}}];
